contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Require a small bounded outputAmount to avoid overflows in the checked environment
    function run(uint256 outputAmount, uint16 feeRate) public payable {
        require(outputAmount > 0 && outputAmount < 1e30, "bad outputAmount");
        require(feeRate <= 5000, "feeRate too high");

        // initialize the pool with sane virtual reserves so buyQuote can compute
        c.initialize(address(0), address(0), uint128(1e18), uint128(1e18 * 2), uint56(0), feeRate, bytes32(0), false, false); if (__ESBMC_reverted()) return;

        // call the view to get the quote
        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount); if (__ESBMC_reverted()) return;

        // General rule: fees are non-negative and netInputAmount is at least feeAmount (i.e., the computed net input covers fees)
        assert(feeAmount + protocolFeeAmount <= netInputAmount && feeAmount <= netInputAmount);
    }

    receive() external payable {}
}

