pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(uint256 outputAmount, uint16 feeRate) internal {
        vm.assume(outputAmount > 0 && outputAmount < 1e30);
        feeRate = uint16(bound(uint256(feeRate), 0, 5000));
        try c.initialize(address(0), address(0), uint128(1e18), uint128(1e18 * 2), uint56(0), feeRate, bytes32(0), false, false) {} catch { return; }
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buyQuote(outputAmount) returns (uint256 __r0, uint256 __r1, uint256 __r2) { netInputAmount = __r0; feeAmount = __r1; protocolFeeAmount = __r2; } catch { return; }
        assertTrue(feeAmount + protocolFeeAmount <= netInputAmount && feeAmount <= netInputAmount);
    }

    function testFuzz_run(uint256 outputAmount, uint16 feeRate) public {
        _run(outputAmount, feeRate);
    }

    receive() external payable {}
}
